        private IEnumerable<HostedEnvironmentFileParam> ActiveFiles()
        {
            if (!Optional.IsCollectionDefined(Files))
            {
                yield break;
            }
            for (int i = 0; i < Files.Count; i++)
            {
                if (!Patch.IsRemoved(Encoding.UTF8.GetBytes($"$.files[{i}]")) && (Files[i] == null || !Files[i].Patch.IsRemoved("$"u8)))
                {
                    yield return Files[i];
                }
            }
        }
